<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{User,Room,Booking}; class DashboardController extends Controller { public function index() { $stats = ["students" => User::where("role","student")->count(), "rooms" => Room::count(), "available_rooms" => Room::where("available",true)->count(), "bookings" => Booking::count(), "waiting" => Booking::where("status","waiting")->count(), "processing" => Booking::where("status","processing")->count(), "approved" => Booking::where("status","approved")->count(), "cancelled" => Booking::where("status","cancelled")->count()]; $recentBookings = Booking::with(["user","room"])->latest("id")->limit(10)->get(); return view("admin.dashboard",compact("stats","recentBookings")); } }
